def line_id(lesson, n): return 'gen.pr.%s.%d' % (lesson.replace('.', ''), n)
def inject(obj):
    '''تضيف predBefore إلى خطوات الاكتشاف في درسٍ له توقّعات'''
    P = PRED.get(obj.get('id')) if isinstance(obj, dict) else None
    if not P or 'flow' not in obj: return
    seen = {}; keys = list(P)
    for st in obj['flow']:
        if not isinstance(st, dict) or st.get('s') != 'explore': continue
        sc = st.get('scene'); k = '%s#%d' % (sc, seen.get(sc, 0)); seen[sc] = seen.get(sc, 0) + 1
        if k in P:
            w, _, *o = P[k]; st['predBefore'] = [w, line_id(obj['id'], keys.index(k))] + ([o[0]] if o else [])
if __name__ == '__main__':
    import json, os
    ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
    p = ROOT + '/content/strings/gen.json'; g = json.load(open(p, encoding='utf8'))
    n = 0
    for les, P in PRED.items():
        for i, (k, v) in enumerate(P.items()): g['lines'][line_id(les, i)] = v[1]; n += 1
    # أعداد الخيارات فوق المئة كلماتها هنا (numberPick يقرأ gen.numw.N): ألف وعشرة آلاف في توقّع «المتر المربع» (m3.u4.d4)
    g['lines']['gen.numw.1000'] = 'أَلْفٌ'; g['lines']['gen.numw.10000'] = 'عَشَرَةُ آلَافٍ'
    # وأعداد توقّعات م4 فوق المئة (الزوايا)
    g['lines'].update({'gen.numw.120': 'مِئَةٌ وَعِشْرُونَ', 'gen.numw.180': 'مِئَةٌ وَثَمَانُونَ', 'gen.numw.200': 'مِئَتَانِ', 'gen.numw.360': 'ثَلَاثُمِئَةٍ وَسِتُّونَ'})
    open(p, 'w', encoding='utf8').write(json.dumps(g, ensure_ascii=False, indent=1) + '\n'); print('ok', n, 'توقّعاً')
